  private validateTransitionBlock(phaseName: string, transitions: TransitionBlock, policyPhases: string[]): void {
    // Validate each transition type
    for (const [key, transition] of Object.entries(transitions)) {
      if (typeof transition === 'string') {
        // String transition - validate phase exists
        if (!policyPhases.includes(transition)) {
          throw new Error(`Invalid ${key} transition in phase '${phaseName}': phase '${transition}' not found in policy`);
        }
      } else if (typeof transition === 'object') {
        // Object transition - validate TransitionConfig structure
        if (!transition.capability || !transition.prompt || !transition.allowed_destinations) {
          throw new Error(`Invalid ${key} transition in phase '${phaseName}': missing required fields`);
        }

        // Validate allowed_destinations
        for (const dest of transition.allowed_destinations) {
          if (!policyPhases.includes(dest)) {
            throw new Error(`Invalid ${key} transition in phase '${phaseName}': destination '${dest}' not found in policy`);
          }
        }

        // Validate confidence thresholds
        if (transition.confidence_thresholds) {
          if (transition.confidence_thresholds.auto_advance < 0 || transition.confidence_thresholds.auto_advance > 1) {
            throw new Error(`Invalid auto_advance threshold in ${key}: must be 0.0-1.0`);
          }
          if (transition.confidence_thresholds.require_approval < 0 || transition.confidence_thresholds.require_approval > 1) {
            throw new Error(`Invalid require_approval threshold in ${key}: must be 0.0-1.0`);
          }
        }
      }
    }
  }
