  ```typescript
  async detectCycles(issueId: string, cycleLength: number = 3): Promise<boolean> {
    const recentDecisions = await this.getDecisionsForIssue(issueId, { limit: 20 });

    // Extract transition sequence from decision log
    const transitions = recentDecisions
      .filter(d => d.type === 'phase_transition')
      .map(d => `${d.metadata?.from_phase}→${d.metadata?.to_phase}`)
      .slice(-10);  // Analyze last 10 transitions

    // Look for A→B→A repeating patterns
    for (let i = 0; i <= transitions.length - cycleLength; i++) {
      const pattern = transitions.slice(i, i + cycleLength);
      const reversePattern = [...pattern].reverse();

      // If pattern matches its reverse, it's oscillating
      if (pattern.join(',') === reversePattern.join(',')) {
        return true;  // Cycle detected
      }
    }
    return false;
  }
  ```
- **Design rationale**:
  - Analyzes recent transition sequences
  - Looks for patterns that reverse themselves (oscillation)
  - Cycle length 3 catches develop→test→develop patterns
  - Configurable sensitivity via cycleLength parameter
  - More sophisticated than simple visit/transition counting
  - Catches complex loops that single limits miss
