- Extend `worker-engine.ts` to handle dynamic_decision transitions:
  ```typescript
  private async executeDecisionAgent(
    issueId: string,
    transition: PhaseTransition
  ): Promise<PhaseTransition> {
    // Select agent based on transitionConfig.capability
    const agent = this.agentRegistry.selectAgent({
      required_capabilities: [transition.dynamic_agent],  // e.g., "test-decision"
      tags: ['decision']
    });

    if (!agent) {
      throw new Error(`No decision agent found with capability: ${transition.dynamic_agent}`);
    }

    // Get issue details
    const issue = await getIssue(issueId);

    // Build decision instructions
    const instructions = this.policyEngine.buildDecisionInstructions(
      issue,
      transition.decision_config,
      this.logger.getRun(this.currentRunId).outcome,
      this.currentPolicy,
      this.currentPhase
    );

    // Launch decision agent with OpenCode CLI
    const result = await this.opencode.runAgentCLI({
      directory: process.cwd(),
      title: `Decision: ${transition.dynamic_agent}`,
      agent: agent.id,
      message: instructions,
    });

    if (!result.success) {
      throw new Error(`Decision agent execution failed: ${result.error}`);
    }

    // Parse decision response
    const decision = this.policyEngine.parseDecisionResponse(
      result.output,
      transition.decision_config
    );

    // Log decision
    this.logger.logDecision({
      run_id: this.currentRunId,
      type: 'dynamic_decision',
      decision: decision.action,
      reasoning: decision.reasoning,
      metadata: {
        capability: transition.dynamic_agent,
        confidence: decision.confidence,
        target_phase: decision.target_phase,
        requires_approval: decision.requires_approval
      }
    });

    // Return resulting transition based on decision
    if (decision.requires_approval) {
      return {
        type: 'block',
        reason: `Decision requires approval: ${decision.reasoning}`
      };
    } else if (decision.target_phase) {
      return {
        type: decision.action.startsWith('jump_to_') ? 'jump_back' : 'advance',
        next_phase: decision.target_phase,
        reason: decision.reasoning
      };
    } else {
      return {
        type: 'close',
        reason: decision.reasoning
      };
    }
  }
  ```
- **Design rationale**:
  - Selects agent based on capability (e.g., test-decision)
  - Builds comprehensive decision instructions
  - Launches decision agent via OpenCode CLI
  - Parses and validates response
  - Logs decision with full metadata
  - Returns PhaseTransition based on decision result
  - Handles require_approval by blocking for HITL

