        private async findReusableSession(issueId: string, target: string): Promise<{ sessionId: string | null; shouldReuse: boolean }> {
      const runs = target === "@shared" 
        ? this.logger.queryRuns({ issue_id: issueId, limit: 1 })
        : this.logger.queryRuns({ issue_id: issueId, phase: target, status: "completed", limit: 1 });

      if (runs.length === 0) return { sessionId: null, shouldReuse: false };

      const sessionId = runs[0].session_id;
      const totalTokens = this.sumTokensForSession(sessionId);
      const maxTokens = this.getMaxTokens();
      const shouldReuse = totalTokens < (maxTokens * this.getThreshold());

      return { sessionId, shouldReuse };
    }
