        async function listSessionsForIssue(issueId: string) {
      const runs = getLogger().queryRuns({ issue_id: issueId });
      const sessionMap = new Map();

      for (const run of runs) {
        if (!sessionMap.has(run.session_id)) {
          sessionMap.set(run.session_id, { phases: [], createdAt: run.created_at, totalTokens: 0 });
        }
        const entry = sessionMap.get(run.session_id);
        entry.phases.push(run.phase);
        entry.totalTokens += run.outcome?.metrics?.tokens_used || 0;
      }

      return Array.from(sessionMap.entries()).map(([sessionId, data]) => ({
        sessionId,
        phases: [...new Set(data.phases)], // Unique phases
        createdAt: data.createdAt,
        totalTokens: data.totalTokens
      })).sort((a, b) => b.createdAt - a.createdAt); // Newest first
    }
